function renderCampaigns(){document.getElementById("app-content").innerHTML=`\n    <div class="page-transition">\n      <div class="actions-bar" style="margin-bottom:20px;">\n        <button class="btn btn-primary" onclick="alert('سيتم إضافة حملة قريباً')">إضافة حملة جديدة</button>\n      </div>\n      <div class="card">\n        <div class="table-container">\n          <table class="data-table">\n            <thead>\n              <tr>\n                <th>اسم الحملة</th>\n                <th>الحالة</th>\n                <th>المرسل</th>\n                <th>نسبة الفتح</th>\n              </tr>\n            </thead>\n            <tbody>\n              ${AppState.campaigns.map(n=>`\n                <tr>\n                  <td>${n.name}</td>\n                  <td>${n.status}</td>\n                  <td>${n.sent}</td>\n                  <td>${n.opened}</td>\n                </tr>\n              `).join("")}\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  `}